function kidIcon(name){const paths={compass:'<circle cx="12" cy="12" r="9"/><path d="m16 8-2.5 5.5L8 16l2.5-5.5L16 8Z"/>',star:'<path d="m12 2 3 6 7 1-5 5 1 7-6-3-6 3 1-7-5-5 7-1Z"/>',flag:'<path d="M5 22V3m0 1c5-5 9 5 15 0v10c-6 5-10-5-15 0"/>',book:'<path d="M3 4c4-2 7-1 9 1 2-2 5-3 9-1v15c-4-2-7-1-9 1-2-2-5-3-9-1ZM12 5v15"/>',lock:'<rect x="5" y="10" width="14" height="11" rx="3"/><path d="M8 10V6a4 4 0 0 1 8 0v4M12 14v3"/>',leaf:'<path d="M4 20C1 7 10 2 21 3c0 11-5 19-17 17ZM4 20 16 8"/>',spark:'<path d="m12 2 2.8 7.2L22 12l-7.2 2.8L12 22l-2.8-7.2L2 12l7.2-2.8Z"/>',arrow:'<path d="M4 12h16m-6-6 6 6-6 6"/>',mountain:'<path d="m2 20 8-15 5 9 3-5 5 11ZM7 11l3 3 3-3"/>',bag:'<rect x="5" y="7" width="14" height="15" rx="4"/><path d="M9 7V5a3 3 0 0 1 6 0v2M5 13h14M9 13v3h6v-3"/>',check:'<path d="m5 12 4 4L19 6"/>',help:'<circle cx="12" cy="12" r="9"/><path d="M9 9a3 3 0 1 1 4 3v2M12 17h.01"/>'};return `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.65" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${paths[name]||paths.compass}</svg>`}
function kidProgress(u){let studied=u?.completed?.length||0,best=Math.max(0,...(u?.attempts||[]).map(a=>a.score));return {studied,best,xp:studied*20+best*10+(u?.story?.completed?160:0)}}
function kidAtlasPage(u){const p=kidProgress(u);return `<div class="kid-atlas"><section class="atlas-welcome"><div><h1>Куда отправимся <em>сегодня?</em></h1><p>Выбирай место на карте. Знакомься с культурой. Собирай открытия!</p></div><a class="explorer-card" href="#${u?'profile':'login'}"><span class="explorer-emblem">${u?.character?gameCharacter(u):'<img src="assets/lynx-guide.png" alt="" width="70" height="86">'}</span><div><strong>${u?esc(u.nick):'Юный исследователь'}</strong><span>${p.studied>=5?'Следопыт':'Начинающий путешественник'} <b>· ${p.xp} опыта</b></span></div><span class="explorer-arrow">↗</span></a></section><div class="atlas-playground"><section class="kid-map-shell" aria-labelledby="kidMapHeading"><div class="kid-map-top"><h2 id="kidMapHeading">${kidIcon('compass')} Твоя карта открытий</h2><button class="map-help" type="button" data-atlas-help aria-label="Как играть на карте">${kidIcon('help')}<span>Как играть?</span></button></div><div class="atlas-map" id="atlasMap"><p>Разворачиваем карту…</p></div><div class="kid-map-bottom"><span><i class="open-dot"></i> Можно отправляться</span><span>${kidIcon('lock')} Скоро откроется</span><span class="map-bottom-hint">Выбери отметку или найди регион</span></div></section><section class="kid-location" id="locationPanel" aria-live="polite">${kidLocationDetails('bashkortostan','Башкортостан',true,u)}</section></div><div class="atlas-bottom-row"><section class="guide-tip">${visitCompanionMarkup()}<div class="guide-bubble"><h2>К кому отправимся в гости?</h2><p>Данияр готовит семейный праздник. Поможем с угощениями и нарядами, познакомимся с языком и историями края.</p><button type="button" class="guide-pick" data-shortcut="bashkortostan">Покажи, где это ${kidIcon('arrow')}</button></div></section><section class="stickerbook"><div class="stickerbook-heading"><div><h2>Значки открытий</h2></div><span>${[p.studied>=1,p.studied>=5,p.best>=4].filter(Boolean).length}<small> / 3</small></span></div><div class="sticker-list">${[{icon:'leaf',title:'Первый шаг',earned:p.studied>=1,key:'first',color:'green'},{icon:'compass',title:'Следопыт',earned:p.studied>=5,key:'trail',color:'gold'},{icon:'star',title:'Исследователь Южного Урала',earned:p.best>=4,key:'expert',color:'rust'}].map(b=>`<button class="sticker ${b.color} ${b.earned?'earned':''}" type="button" data-reward="${b.key}" aria-label="${b.title}: ${b.earned?'получен':'узнать, как получить'}"><span class="sticker-medal">${kidIcon(b.icon)}${b.earned?`<i>${kidIcon('check')}</i>`:''}</span><strong>${b.title}</strong><small>${b.earned?'Получен!':'Как получить?'}</small></button>`).join('')}</div></section></div><dialog class="atlas-dialog" id="atlasDialog" aria-label="Подсказка для путешественника"><button class="dialog-close" aria-label="Закрыть окно" type="button">×</button><div id="atlasDialogContent"></div></dialog></div>`}
function kidLocationDetails(id,name,available,u){const story=u?.story||{},done=!!story.completed,n=done?8:Math.min(7,story.step||0);return `<div class="location-postcard"><img src="assets/ural-postcard.jpg" alt="Пейзаж Южного Урала"></div><div class="kid-location-body"><h2>${esc(name)}</h2><p>${available?'Данияр зовёт помочь семье подготовиться к Сабантую. Приготовим угощения, украсим наряды и познакомимся с языком и историями края.':'Эта глава ещё готовится. Пока можно отправиться в гости к Данияру в Башкортостан.'}</p>${available?`<div class="quest-facts"><span>${kidIcon('book')} 8 сцен</span><span>${kidIcon('compass')} ~20 минут</span></div><div class="quest-progress"><span>Твоя история<b>${n} / 8</b></span><div class="quest-steps" aria-label="Пройдено ${n} из 8 сцен">${Array.from({length:8},(_,i)=>`<i class="${i<n?'complete':''}">${i<n?kidIcon('check'):'<span></span>'}</i>`).join('')}</div></div><a class="kid-primary" href="#${u?'book/bashkortostan':'login'}">${done?'Открыть книгу':n?'Продолжить историю':'Отправиться в гости'} ${kidIcon('arrow')}</a><span class="quest-reward">${kidIcon('bag')} ${done?'Бүрек и курай уже в рюкзаке':'За помощь — бүрек и значок курая'}</span>`:`<button type="button" class="kid-primary" data-shortcut="bashkortostan">К первому маршруту ${kidIcon('arrow')}</button>`}</div>`}
function wireKidAtlas(){const root=document.querySelector('.kid-atlas');root.addEventListener('click',e=>{const d=document.getElementById('atlasDialog'),body=document.getElementById('atlasDialogContent');if(e.target.closest('[data-atlas-help]')){body.innerHTML=`<span class="dialog-symbol">${kidIcon('compass')}</span><h2>Как исследовать карту</h2><ol><li><strong>Выбери отметку.</strong> Золотой компас — открытый маршрут. Можно нажать и на сам регион.</li><li><strong>Рассмотри поближе.</strong> Нажми +, передвигай карту пальцем или мышью. На телефоне работает увеличение двумя пальцами.</li><li><strong>Отправляйся в путь.</strong> Помоги семье приготовить стол, укрась наряды и поговори с хозяевами.</li><li><strong>Собирай значки.</strong> Предмет одежды и значок региона останутся в твоём рюкзаке.</li></ol><p>Начать можно с Башкортостана. Остальные экспедиции готовятся.</p>`;d.showModal()}const reward=e.target.closest('[data-reward]');if(reward){const info={first:['leaf','Первый шаг','Изучи одну тему и правильно ответь на вопрос после неё. Первое открытие попадёт в твой дневник.'],trail:['compass','Следопыт','Изучи все пять тем Башкортостана. Каждый правильный ответ в конце темы приближает тебя к значку.'],expert:['star','Исследователь Южного Урала','Пройди итоговое испытание и ответь верно хотя бы на четыре вопроса из пяти. Если не получилось — можно попробовать снова.']}[reward.dataset.reward];body.innerHTML=`<span class="dialog-symbol">${kidIcon(info[0])}</span><h2>${info[1]}</h2><p>${info[2]}</p><a class="kid-primary" href="#${user()?'region':'login'}">Вперёд за открытиями ${kidIcon('arrow')}</a>`;d.showModal()}if(e.target.closest('.dialog-close'))d.close();const shortcut=e.target.closest('[data-shortcut]');if(shortcut){const id=shortcut.dataset.shortcut,pin=document.querySelector(`[data-location="${id}"] .pin-core`);if(root.mapController){root.mapController.select(id,true);document.getElementById(innerWidth<900?'locationPanel':'kidMapHeading').scrollIntoView({block:'center',behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'})}}});document.getElementById('atlasDialog').addEventListener('click',e=>{if(e.target===e.currentTarget){const r=e.currentTarget.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.currentTarget.close()}})}
